"""Pinning store and fingerprint utilities for Tessaro feeds."""

import hashlib
import json
from pathlib import Path
from typing import Dict, Optional

PIN_DATA_FILE = Path(__file__).parent / "pins.json"


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """A store of pinned certificate fingerprints per host."""

    def __init__(self, pins: Dict[str, str]):
        self._pins = pins

    @classmethod
    def load(cls) -> "PinStore":
        """Load the pin store from the default data file."""
        if PIN_DATA_FILE.exists():
            data = json.loads(PIN_DATA_FILE.read_text())
        else:
            data = {}
        return cls(data)

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches the pinned value for the host."""
        expected = self._pins.get(host)
        if expected is None:
            return False
        return fp == expected
